from pathlib import Path
import json,base64,re,shutil
from fontTools import subset
from fontTools.ttLib import TTFont
P=Path(__file__).resolve().parents[1]; S=P/'source'
slides=[]
def page(k,title,body,cls=''):
 n=len(slides)+1
 slides.append(f'<section class="slide {cls}" data-title="{title}"><header><div class="slide-kicker">{k}</div><h2 class="slide-title">{title}</h2><div class="slide-rule"></div></header><div class="content is-vertically-centered">{body}</div><footer class="footer"><span>動画一本を、教材へ。</span><span class="page-number"> / 07</span></footer></section>')
slides.append('''<section class="slide simple-title-cover dark" data-title="動画一本を、教材へ。"><header class="default-opening-main"><div class="slide-kicker">CREATOR LEARNING WORKFLOW</div><h1 class="slide-title">動画一本を、<br>教材へ。</h1><p class="slide-subtitle">伝えた内容を、学べる順序に組み直す。</p><div class="cover-meta">動画制作者のための制作工程 / 架空の企画例</div></header><footer class="footer"><span>素材・主張・章・図解・小テスト・再利用</span><span class="page-number"> / 07</span></footer></section>''')
page('01 / 素材と主張','教材の入口は「学習後に何ができるか」', '''<div class="outcome-support is-fit-content"><article class="outcome-card"><span class="concept-label">架空の教材テーマ</span><strong>スマホ撮影で、被写体に合う光を選べる</strong><p>動画例「窓際で撮る、商品写真の基本」を教材化する。</p></article><div class="support-stack"><article><strong>素材を確認する</strong><span>動画、字幕、実演カットを照合。権利と公開範囲を記録する。</span></article><article><strong>主張を一文にする</strong><span>「光の方向で、形の見え方が変わる」。実演で説明できる範囲に絞る。</span></article><article><strong>到達点を決める</strong><span>学習者が新しい被写体でも光の方向を選び、理由を説明する。</span></article></div></div>''')
page('02 / チャプター','章は話した順序より、判断の順序で組む', '''<table class="comparison-table"><thead><tr><th>学習の章</th><th>素材の役割</th><th>学習者の行動</th><th>編集の判断</th></tr></thead><tbody><tr><td class="row-head">光を見つける</td><td>窓と被写体の位置を示す<span class="keep-word">実演</span></td><td>光が来る方向を指す</td><td>位置関係が見えるカットを残す</td></tr><tr><td class="row-head">見え方を比べる</td><td>正面光と側面光の比較</td><td>影と輪郭の違いを説明する</td><td>同じ被写体・条件の比較を並べる</td></tr><tr><td class="row-head">目的に合わせる</td><td>立体感を出す選択の解説</td><td>撮影の目的から光を選ぶ</td><td>選択理由を字幕で補う</td></tr><tr><td class="row-head">自分で試す</td><td>別の被写体への応用</td><td>撮影し、選択を振り返る</td><td>課題と確認観点を渡す</td></tr></tbody></table><div class="callout">章ごとに、到達点へつながる「一つの行動」を置く。</div>''')
page('03 / 制作工程','各工程の出力を、次の工程の入力にする', '''<div class="process-flow is-fit-content" style="grid-template-columns:repeat(6,1fr)">'''+''.join(f'<article class="process-step"><span>{i}</span><strong>{a}</strong><p>{b}</p></article>' for i,(a,b) in enumerate([('素材','字幕と映像を照合した素材表'),('主張','教える範囲を定めた一文'),('章','行動と素材を対応させた章立て'),('図解','判断に必要な関係の説明'),('小テスト','到達点を確かめる設問と解説'),('再利用','出典・版・権利を添えた教材部品')],1))+'''</div><div class="callout">見栄えを整える前に、主張と素材の対応を確認する。</div>''')
page('04 / 図解','図解の型は、説明する関係で選ぶ', '''<div class="issue-tree is-fit-content"><div class="tree-column"><div class="tree-node tree-root">何を理解して<br>ほしいか</div></div><div class="tree-column"><div class="tree-node">順序を理解する</div><div class="tree-node">違いを比較する</div><div class="tree-node">理由を説明する</div></div><div class="tree-column"><div class="tree-node"><strong>工程図</strong><br>被写体を置く、光を確認、撮影、見直し</div><div class="tree-node"><strong>比較表</strong><br>正面光と側面光の影・輪郭を同じ観点で並べる</div><div class="tree-node"><strong>関係図</strong><br>光の方向、影、見える立体感を結ぶ</div></div></div><div class="callout">映像でしか分からない動きは、実演カットを残す。</div>''')
page('05 / 小テスト','小テストは、章の到達点と同じ行動を問う', '''<div class="input-process-output-layers is-fit-content"><article class="ipo-layer"><span class="concept-label">設問例</span><strong>凹凸を見せたい</strong><span>同じ被写体を、正面光と側面光で撮った。どちらを選ぶ？</span></article><span class="ipo-arrow" aria-hidden="true"></span><article class="ipo-layer is-process"><span class="concept-label">回答と理由</span><strong>側面光を選ぶ</strong><span>この実演条件では、横からの光で影が生まれ、凹凸が見えやすい。選択と理由をセットで答える。</span></article><span class="ipo-arrow" aria-hidden="true"></span><article class="ipo-layer"><span class="concept-label">確認と再学習</span><strong>比較の章へ戻る</strong><span>影の違いが分からなければ、同じ条件の比較カットを見直す。</span></article></div><p class="small-note">架空の設問例。教材の実演条件に合わせて正答・例外を確認する。</p>''')
page('06 / 再利用','再利用の前に、教材部品の根拠と権利を確かめる', '''<table class="decision-log"><thead><tr><th>公開前の確認</th><th>残す記録</th><th>通過条件</th><th>未確認の場合</th></tr></thead><tbody><tr><td>主張と素材の対応</td><td>元動画の位置・字幕・章ID</td><td>説明の文脈が一致する</td><td>原典に戻って修正</td></tr><tr><td>図解と小テストの整合</td><td>到達点・正答・解説</td><td>教えた判断を問う</td><td>設問を組み直す</td></tr><tr><td>利用権と公開範囲</td><td>制作者・許諾範囲・素材の出典</td><td>配布先に必要な権利がある</td><td>該当素材を外す</td></tr><tr><td>版と更新責任</td><td>教材の版・変更理由・更新担当</td><td>差替え先を追跡できる</td><td>配布を保留する</td></tr></tbody></table><div class="callout">次の一歩：一章だけ試作し、学習者が選択理由を説明できるか確かめる。</div><p class="small-note">架空・未実施の企画例。学習効果、制作時間、収益の実績は示していません。</p>''')
css='''/* Japanese derivative of NomiciAI/mbb-page-maker; upstream root Apache-2.0. */
.slide-title{font-size:48px;line-height:1.3}.simple-title-cover .slide-title{font-size:100px;line-height:1.23}.slide-kicker{font-size:18px;letter-spacing:.16em}.slide-subtitle{font-size:34px}.cover-meta{font-size:22px}.content{gap:32px}.outcome-card strong{font-size:32px}.outcome-card p,.support-stack span{font-size:24px;line-height:1.65}.support-stack strong{font-size:30px}.outcome-support{height:auto!important}.support-stack{height:auto!important}.process-flow{height:auto!important}.process-step{min-height:290px}.process-step strong{font-size:29px}.process-step p{font-size:23px;line-height:1.6}.process-step span{font-size:20px;width:42px;height:42px}.comparison-table{font-size:25px}.comparison-table td,.comparison-table th{padding:24px;line-height:1.55}.decision-log{font-size:24px}.decision-log td,.decision-log th{padding:22px;line-height:1.5}.callout{font-size:27px;line-height:1.5;height:auto!important}.issue-tree{height:auto!important}.tree-node{font-size:28px;line-height:1.6;padding:22px 26px}.tree-root{font-size:34px}.input-process-output-layers{height:auto!important}.ipo-layer strong{font-size:32px;margin:14px 0}.ipo-layer span{font-size:25px;line-height:1.6}.ipo-layer .concept-label{font-size:18px}.small-note{font-size:19px;color:var(--color-muted);margin:0}.nav{position:fixed;bottom:12px;right:18px;display:flex;gap:8px;z-index:10}.nav button{background:#063b78;color:white;border:0;padding:8px 14px;font-size:15px;cursor:pointer}.is-export .nav,.is-print .nav{display:none} .is-overview{overflow:auto} @media print{@page{size:1600px 900px;margin:0}.slide,.slide.active{width:1600px!important;height:900px!important;min-height:900px!important;max-height:900px!important;transform:none!important}html,body{width:1600px!important}.nav{display:none!important}}
'''
css += '\n/* Initial display correction: prevent flex from splitting Japanese exhibit labels. */\n.issue-tree .tree-node{display:block;line-height:1.4;padding:20px 24px}\n'
css+='\n.process-flow{gap:36px;overflow:visible}.process-step{overflow:visible;padding-left:14px;padding-right:14px}.process-step:not(:last-child)::after{right:-26px;top:48%;width:14px;height:14px}.keep-word{white-space:nowrap}\n'
css+='\n.simple-title-cover .default-opening-main .slide-title{font-size:100px;line-height:1.23}.footer{font-size:15px}.page-number{font-size:14px;color:var(--color-muted)}\n'
(S/'assets/css/deck-ja.css').write_text(css)
fontcss=':root{--font-sans:"Noto Sans CJK JP",sans-serif;--font-serif:var(--font-sans);--font-cjk-sans:var(--font-sans);--font-cjk-serif:var(--font-serif)}'
(S/'assets/css/fonts.css').write_text('@font-face{font-family:"Noto Sans CJK JP";src:url(../fonts/noto-ja-subset.otf);font-weight:100 900;font-display:swap}'+fontcss)
# Use the original runtime byte-for-byte; a small catalog bridge only sends original arrow-key events.
js=(S/'upstream/assets/js/runtime.js').read_text('utf-8')
(S/'assets/js').mkdir(exist_ok=True)
(S/'assets/js/runtime.js').write_bytes((S/'upstream/assets/js/runtime.js').read_bytes())
bridge='''addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='yebisu-slide'||!Number.isInteger(e.data.index))return;for(let i=0;i<7;i++)document.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',bubbles:true}));for(let i=0;i<Math.max(0,Math.min(6,e.data.index));i++)document.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));});if(parent!==window)new MutationObserver(()=>{const ss=[...document.querySelectorAll('.slide')];const index=ss.findIndex(s=>s.classList.contains('active'));if(index>=0)parent.postMessage({type:'yebisu-page',index,total:ss.length},location.origin)}).observe(document.querySelector('.deck'),{subtree:true,attributes:true,attributeFilter:['class']});'''
(S/'catalog-bridge.js').write_text(bridge,'utf-8')
head='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>動画一本を、教材へ。</title>'
order=['assets/css/fonts.css','assets/css/base.css','assets/css/layouts.css','assets/css/components.css','assets/css/illustrations.css','assets/themes/blue.css','assets/css/deck-ja.css']
body='<main class="deck" data-deck-title="動画一本を、教材へ。">'+''.join(slides)+'</main>'
(S/'index.html').write_text(head+''.join(f'<link rel="stylesheet" href="{f}">' for f in order)+'</head><body>'+body+'<script src="assets/js/runtime.js"></script><script src="catalog-bridge.js"></script></body></html>')
# Embed verified OSS subset, replacing upstream webfont declarations.
chars=''.join(slides)+'一覧次のページ前0123456789 /←→'
f=TTFont(S/'fonts/NotoSansCJKjp-Regular.otf'); opts=subset.Options();sub=subset.Subsetter(options=opts);sub.populate(text=chars);sub.subset(f);f.save(S/'noto-ja-subset.otf')
(S/'assets/fonts').mkdir(exist_ok=True)
shutil.copy2(S/'noto-ja-subset.otf',S/'assets/fonts/noto-ja-subset.otf')
embedded='@font-face{font-family:"Noto Sans CJK JP";src:url(data:font/otf;base64,'+base64.b64encode((S/'noto-ja-subset.otf').read_bytes()).decode()+');font-weight:100 900;font-display:swap}'+fontcss
html=head+'<style>'+embedded+'\n'+''.join((S/f).read_text() for f in order[1:])+'</style></head><body>'+body+'<script>'+js+'</script><script>'+bridge+'</script></body></html>'
(P/'index.html').write_text(html)
(P/'input/BRIEF.md').write_text('# 動画一本を、教材へ。\n\n架空・未実施の企画例。動画制作者が一本の説明動画を教材へ変える工程を説明する。到達点は、光の方向を選び理由を説明すること。素材、主張、章、図解、小テスト、再利用の順で、各工程の出力を引き継ぐ。実績、収益、制作時間の改善を捏造しない。私的資料を使わない。\n')
(P/'input/data.json').write_text(json.dumps({'fictional':True,'implemented':False,'title':'動画一本を、教材へ。','audience':'動画制作者','video_example':'窓際で撮る、商品写真の基本','learning_goal':'被写体に合う光を選び、理由を説明する','stages':['素材','主張','チャプター','図解','小テスト','再利用'],'chapters':['光を見つける','見え方を比べる','目的に合わせる','自分で試す'],'metrics':None},ensure_ascii=False,indent=2))
(P/'PROMPT.txt').write_text('原典starterとCSS6層、content-to-exhibit-routerの論理を使い、BRIEFの架空企画「動画一本を、教材へ。」を日本語7頁の1600×900 HTMLデッキにしてください。効果実績は捏造しない。工程・比較表・関係図・小テスト例・再利用ゲートを適切な原典コンポーネントで表現。固定の公式Noto Sans JPを使用し、元runtime.jsとGolden Pathのquality/contrast/fit/renderを実行。日本語の矢印と語中改行を直し、全7頁を描画・目視。実行できない工程は別記録。')
print(P)
